function wx19DrawPanel(r){$('#wx19Panel')?.remove();const bar=$('.chat-bar');if(!bar||!wx19.panel)return;const panel=document.createElement('div');panel.id='wx19Panel';panel.className='wx19-panel';bar.append(panel);if(wx19.panel==='plus'){panel.innerHTML=`<div class="plus-grid">${[['image','相册','image'],['camera','拍摄','camera'],['video','视频通话','video'],['voice','语音通话','phone'],['location','位置','pin'],['redpacket','红包','rp'],['transfer','转账','tf'],['contact','个人名片','card']].map(([a,n,i])=>`<button data-inline="${a}"><span>${wx19Icon(i,26)}</span>${n}</button>`).join('')}</div><input hidden type="file" id="wx19PhotoFile" accept="image/png,image/jpeg,image/webp"><input hidden type="file" id="wx19CameraFile" accept="image/*" capture="environment">`;const upload=async e=>{const file=e.target.files[0];if(!file)return;try{const key='chat-photo:'+crypto.randomUUID();await mediaWrite(key,await prepareImage(file,1600));wx19.panel=null;await sendMessage(r,'[图片]',null,{extra:{media:{type:'image',key}}})}catch(err){toast(err.message)}};$('#wx19PhotoFile').onchange=upload;$('#wx19CameraFile').onchange=upload;panel.querySelectorAll('[data-inline]').forEach(b=>b.onclick=()=>{const a=b.dataset.inline;if(r.file&&['voice','video','redpacket','transfer'].includes(a)){toast('文件传输助手只用于本地收纳，不支持收付款或通话');return}if(a==='image')return $('#wx19PhotoFile').click();if(a==='camera')return $('#wx19CameraFile').click();if(a==='voice'||a==='video'){if(!apiReady()||!voiceReady()||!voiceSettings.stt){panel.innerHTML='<div class="inline-note">先到「我 → 小手机专栏 → 聊天 API / 语音 API」配置通话接口。</div>';return}wx19.panel=null;wx19DrawPanel(r);wxStartCall(r,a)}else if(a==='redpacket'||a==='transfer')wx19GiftForm(r,a,panel);else wx19CardForm(r,a,panel)})}else if(wx19.panel==='emoji'){panel.innerHTML=`<div class="p-tabs"><button id="wx19EmojiTab">表情</button><button id="wx19StickerTab">贴纸</button></div><div class="emo-grid">${['😀','😊','🥰','😘','🥺','😭','😂','😳','😴','😡','🤗','🙄','👍','❤️','🌷','✨','🎉','🙏','💕','😋','😎','🤔','😔','🥹'].map(v=>`<button data-emoji="${v}">${v}</button>`).join('')}</div>`;panel.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{const f=$('#composer textarea'),a=f.selectionStart??f.value.length;f.value=f.value.slice(0,a)+b.dataset.emoji+f.value.slice(f.selectionEnd??a);f.dispatchEvent(new Event('input'))});$('#wx19StickerTab').onclick=()=>wx19StickerGrid(r,panel);$('#wx19EmojiTab').onclick=()=>wx19DrawPanel(r)}$('#messages').scrollTop=$('#messages').scrollHeight}
function wx19StickerGrid(r,panel){panel.querySelector('.emo-grid').innerHTML=[...basicStickers,...customAvailable()].map((s,i)=>`<button data-inline-sticker="${i}" title="${escapeHtml(s.name)}">${s.custom?`<img src="${mediaCache.get('sticker:'+s.id)}" alt="${escapeHtml(s.name)}">`:escapeHtml(s.emoji||'🌷')}</button>`).join('');panel.querySelectorAll('[data-inline-sticker]').forEach(b=>b.onclick=()=>{const s=[...basicStickers,...customAvailable()][Number(b.dataset.inlineSticker)];wx19.panel=null;sendMessage(r,'[表情包：'+s.name+']',null,{sticker:s})})}
function wx19GiftForm(r,type,panel){panel.innerHTML=`<form id="wx19Gift" class="inline-form"><div class="inline-title"><button type="button" id="wx19PanelBack">‹</button><b>${type==='redpacket'?'发红包':'转账'}</b><span>零钱 ¥${PalaisWallet.money(wallet.balance)}</span></div>${r.members?`<select name="recipient" aria-label="收款人">${r.members.map(id=>roles.find(x=>x.id===id)).filter(Boolean).map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join('')}</select>`:''}<input name="amount" inputmode="decimal" required placeholder="金额（元）${type==='redpacket'?' · 最多200':''}" aria-label="金额"><input name="note" maxlength="80" placeholder="${type==='redpacket'?'恭喜发财，大吉大利':'添加留言'}" aria-label="留言"><button class="primary full">${type==='redpacket'?'塞钱进红包':'转账'}</button></form>`;$('#wx19PanelBack').onclick=()=>{wx19.panel='plus';wx19DrawPanel(r)};$('#wx19Gift').onsubmit=e=>{e.preventDefault();if(busy)return toast('请等本轮回复结束');try{const f=e.target,cents=PalaisWallet.cents(f.amount.value);if(type==='redpacket'&&cents>20000)throw Error('单个红包最多 200 元');if(cents>wallet.balance)throw Error('零钱余额不足');const card={type,amount:PalaisWallet.amount(cents),note:f.note.value.trim(),status:'sent',recipient:r.members?f.recipient.value:r.id};wx19.panel=null;sendMessage(r,card.note||'给你发了'+(type==='redpacket'?'红包':'转账'),card)}catch(e){toast(e.message)}}}
function wx19CardForm(r,type,panel){panel.innerHTML=`<form id="wx19Card" class="inline-form"><div class="inline-title"><button type="button" id="wx19PanelBack">‹</button><b>${type==='contact'?'发送名片':'发送位置'}</b></div>${type==='contact'?`<select name="person" aria-label="联系人">${roles.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.name)}</option>`).join('')}</select>`:'<input name="place" required maxlength="200" placeholder="填写位置名称或地址" aria-label="位置">'}<button class="primary full">发送</button></form>`;$('#wx19PanelBack').onclick=()=>{wx19.panel='plus';wx19DrawPanel(r)};$('#wx19Card').onsubmit=e=>{e.preventDefault();const f=e.target,person=roles.find(x=>x.id===f.person?.value);if(type==='contact'&&!person)return;const media=type==='contact'?{type,roleId:person.id}:{type:'location',label:f.place.value.trim()};wx19.panel=null;sendMessage(r,type==='contact'?'[名片] '+person.name:'[位置] '+media.label,null,{extra:{media}})}}
const wx19PriorHold=wxHoldButton;wxHoldButton=function(r){const input=$('#composer textarea');if($('#wxHoldSpeak')){wx19PriorHold(r);input.hidden=false;$('#wxHold').innerHTML=wx19Icon('voice');return}wx19.panel=null;wx19DrawPanel(r);wx19PriorHold(r);const hold=$('#wxHoldSpeak');if(hold){$('#composer').insertBefore(hold,$('#wxEmoji'));hold.classList.add('hold');hold.textContent='按住 说话';input.hidden=true;$('#wxHold').innerHTML=wx19Icon('kbd')}};
function wx19Sheet(html){$('#wx19SheetLayer')?.close();const layer=document.createElement('div');layer.id='wx19SheetLayer';layer.className='wx19-sheet-layer';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','微信操作');layer.innerHTML=`<div class="wx19-mask"></div><section class="wx19-sheet-box">${html}<button class="wx19-cancel">取消</button></section>`;const abort=new AbortController();layer.close=()=>{abort.abort();layer.remove()};layer.querySelector('.wx19-mask').onclick=layer.querySelector('.wx19-cancel').onclick=layer.close;document.addEventListener('keydown',e=>{if(e.key==='Escape')layer.close()},{signal:abort.signal});$('.phone').append(layer);return layer}
const wx19PriorFind=findConversation;findConversation=function(id){return id==='wx-file'?wx19File:wx19PriorFind(id)};
function wx19OpenFile(){try{if(!histories['wx-file'])wxHistoryCommit('wx-file',[]);current='wx-file';go('chat')}catch(e){toast(e.message)}}
const wx19PriorSend=sendMessage;sendMessage=async function(r,text,card=null,options={}){if(!r.file)return wx19PriorSend(r,text,card,options);if(card)return false;try{const m={id:crypto.randomUUID(),role:'user',createdAt:Date.now(),content:text,...options.extra,...(options.sticker?{sticker:options.sticker}:{}),...(wxQuote?.conversationId===r.id?{quote:wxQuote}:{})};wx19State({...histories,[r.id]:[...(histories[r.id]||[]),m]},{...wx18,drafts:{...wx18.drafts,[r.id]:''}},notices);wxQuote=null;renderConversation();return true}catch(e){toast(e.message);return false}};
render();
